"""Labelled AI datasets generated by running the twin across the envelope: Phase 9 (FR16.1, AIQ-5, CON-10).

RULES (BUILD_STEPS.md, Phase 9, fixed before this code): every sampling, noise, fault and split
setting is read from plasma_twin/config/ai_datasets.toml, locked on 2026-11-04 before any model was
trained. The dataset ID is a hash of that file, the twin version and the stage. The same seed gives
identical rows: each row's random numbers come from its own generator, seeded by (locked seed, row index),
so the result does not depend on how many processes build it. Faults are made by the twin or the
instrument model, never by editing labels. Models are trained on twin data only.
"""
from __future__ import annotations

import hashlib
import json
import tomllib
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path
from typing import Any, Callable

import numpy as np
import pandas as pd
from scipy.stats import qmc

from plasma_twin import TWIN_VERSION
from plasma_twin.config.loader import load_envelope

SETTINGS_PATH = Path(__file__).resolve().parents[1] / "config" / "ai_datasets.toml"
DATA_DIR = Path(__file__).resolve().parents[2] / "data" / "ai"


def data_dir() -> Path:
    """data/ai, or the folder PLASMA_TWIN_AI_DATA names (screen tests)."""
    import os
    moved = os.environ.get("PLASMA_TWIN_AI_DATA")
    return Path(moved) if moved else DATA_DIR
FAULT_TYPES = ("probe_contamination", "wavelength_shift", "air_leak", "power_error", "rf_failure")
AIR_N2, AIR_O2 = 0.78, 0.21  # air composition used for the leak (ai_datasets.toml)


def load_settings(path: Path = SETTINGS_PATH) -> dict[str, Any]:
    """The locked dataset settings (ai_datasets.toml), fixed before any training (AIQ-5)."""
    with open(path, "rb") as handle:
        return tomllib.load(handle)


def dataset_id(stage: int, path: Path = SETTINGS_PATH) -> str:
    """A hash of the locked settings, the twin version and the stage: a changed setting gives a new ID."""
    digest = hashlib.sha256(path.read_bytes() + f"|twin {TWIN_VERSION}|stage {stage}".encode()).hexdigest()
    return f"S{stage}-{digest[:10]}"


def _row_rng(seed: int, index: int) -> np.random.Generator:
    return np.random.default_rng([seed, index])


# ------------------------------------------------------------------------------------ Stage 1 sampling
def stage1_plan(settings: dict[str, Any], runs: int | None = None) -> list[dict[str, Any]]:
    """The recorded inputs of every row, with its fault (if any). Deterministic in the locked seeds."""
    s1, faults = settings["stage1"], settings["faults"]
    n = runs or s1["runs"]
    env = load_envelope()["stage1"]
    unit = qmc.LatinHypercube(d=len(s1["continuous"]), seed=s1["seed"]).random(n)
    lows = [env[k]["min"] for k in s1["continuous"]]
    highs = [env[k]["max"] for k in s1["continuous"]]
    values = qmc.scale(unit, lows, highs)
    rng = np.random.default_rng(s1["seed"])
    fault_rng = np.random.default_rng(faults["seed"])
    faulty = fault_rng.permutation(n)[: int(round(faults["fraction"] * n))]
    fault_of = {int(i): FAULT_TYPES[k % len(FAULT_TYPES)] for k, i in enumerate(faulty)}
    plan = []
    for i in range(n):
        mixture = str(rng.choice(s1["mixtures"]))
        low, high = s1["admixture_percent"]
        row = {"index": i, **{k: float(v) for k, v in zip(s1["continuous"], values[i])}, "mixture": mixture,
               "n2_percent": float(rng.uniform(low, high)) if "N2" in mixture else 0.0,
               "o2_percent": float(rng.uniform(low, high)) if "O2" in mixture else 0.0,
               "fault": fault_of.get(i, "none")}
        if row["fault"] != "none":
            key = {"probe_contamination": "probe_contamination_ohm", "wavelength_shift": "wavelength_shift_nm",
                   "air_leak": "air_leak_percent", "power_error": "power_error_percent", "rf_failure": "rf_residual_v"}[row["fault"]]
            magnitude = float(fault_rng.uniform(*faults[key]))
            if row["fault"] == "power_error":
                magnitude *= float(fault_rng.choice([-1.0, 1.0]))
            row["fault_magnitude"] = magnitude
        else:
            row["fault_magnitude"] = 0.0
        plan.append(row)
    return plan


def stage1_line_wavelengths() -> list[float]:
    """The CR-model Ar I lines inside the locked window: the OES feature columns, in a fixed order."""
    from plasma_twin.oes.cr_model import level_data
    low, high = load_settings()["stage1"]["spectrometer"]["window_nm"]
    return sorted(line.wavelength_nm for line in level_data().lines if low <= line.wavelength_nm <= high)


def _contaminated(voltage: np.ndarray, current: np.ndarray, resistance_ohm: float, sweep: np.ndarray) -> np.ndarray:
    """I(V_applied) for a tip with a series resistance: the probe itself sees V_applied - I R."""
    applied = voltage + current * resistance_ohm  # increasing, since I rises with V and R > 0
    return np.interp(sweep, applied, current)


def stage1_row(row: dict[str, Any], settings: dict[str, Any]) -> dict[str, Any]:
    """Run the twin and the virtual instruments for one row; the fault, if any, is made physically."""
    from plasma_twin.oes.boltzmann import integrated_intensities
    from plasma_twin.oes.cr_model import level_data
    from plasma_twin.oes.spectrum import Spectrum, SpectrometerSettings, spectrum_for
    from plasma_twin.probe.iv_model import ProbeSettings, generate, plasma_from
    from plasma_twin.services import stage1
    from plasma_twin.stage1.global_model import solve

    s1 = settings["stage1"]
    rng = _row_rng(s1["seed"], row["index"])
    config = {**stage1.default_config(), **{k: row[k] for k in ("rf_power_w", "pressure_mbar", "ar_flow_sccm", "mixture",
                                                                "n2_percent", "o2_percent")}, "eedf": s1["eedf"], "spatial": s1["spatial"]}
    actual = dict(config)
    if row["fault"] == "air_leak":  # the plasma gets air the record does not know about
        actual["mixture"] = "Ar+N2+O2"
        actual["n2_percent"] = config["n2_percent"] + AIR_N2 * row["fault_magnitude"]
        actual["o2_percent"] = config["o2_percent"] + AIR_O2 * row["fault_magnitude"]
    if row["fault"] == "power_error":
        actual["rf_power_w"] = config["rf_power_w"] * (1 + row["fault_magnitude"] / 100)
    result = solve(stage1.to_inputs(actual), check_envelope=False)

    # OES: noisy synthetic spectrum with a calibration tilt, then line areas as on M5
    spec = s1["spectrometer"]
    low, high = spec["window_nm"]
    spectrum = spectrum_for(result, SpectrometerSettings(spec["fwhm_nm"], low, high, spec["noise_percent_of_peak"],
                                                         seed=int(rng.integers(2**31))))
    tilt = rng.uniform(-1, 1) * spec["calibration_drift_percent"] / 100
    intensity = spectrum.intensity * (1 + tilt * (spectrum.wavelength_nm - (low + high) / 2) / ((high - low) / 2))
    wavelength = spectrum.wavelength_nm + (row["fault_magnitude"] if row["fault"] == "wavelength_shift" else 0.0)
    measured = Spectrum(wavelength, intensity, {}, spectrum.settings, spectrum.gas_temperature_k)
    lines = [line for line in level_data().lines if low <= line.wavelength_nm <= high]
    areas = {f"line_{p.wavelength_nm:.3f}": p.intensity for p in integrated_intensities(measured, lines)}

    # probe: noise-free curve, the fault, then the locked noise
    probe = ProbeSettings.defaults(noise_percent=0.0, rf_amplitude_v=row["fault_magnitude"] if row["fault"] == "rf_failure" else 0.0)
    curve = generate(plasma_from(result), probe)
    current = curve.current_a
    if row["fault"] == "probe_contamination":  # V_applied >= V_probe, so the normal sweep covers every applied voltage
        current = _contaminated(curve.voltage_v, curve.current_a, row["fault_magnitude"], curve.voltage_v)
    current = current + rng.normal(0.0, s1["probe"]["noise_percent"] / 100 * curve.electron_current_at_vp_a, current.shape)
    probe_columns = {f"iv_{k:03d}": float(v) for k, v in enumerate(current)}
    return {**row, "te_ev": result.te_ev, "ne_m3": result.ne_center_m3, "tgas_k": result.inputs.gas_temperature_k,
            "calibration_tilt": tilt, **areas, **probe_columns}


# ------------------------------------------------------------------------------------ Stage 2
def stage2_plan(settings: dict[str, Any], runs: int | None = None) -> list[dict[str, Any]]:
    """The Stage 2 run plan: a Latin hypercube over the continuous inputs plus the discrete choices, from the locked seed."""
    s2 = settings["stage2"]
    n = runs or s2["runs"]
    env = load_envelope()["stage2"]
    ranges = {k: (env[k]["min"], env[k]["max"]) if k in env else None for k in s2["continuous"]}
    ranges["width_us"] = tuple(s2["width_us"])
    ranges["frequency_khz"] = (env["pulse_frequency_khz"]["min"], env["pulse_frequency_khz"]["max"])
    ranges["power_w"] = (env["average_power_w"]["min"], env["average_power_w"]["max"])
    unit = qmc.LatinHypercube(d=len(s2["continuous"]) + 1, seed=s2["seed"]).random(n)
    rng = np.random.default_rng(s2["seed"])
    share_low, share_high = s2["power_share"]
    plan = []
    for i in range(n):
        row = {"index": i}
        for j, key in enumerate(s2["continuous"]):
            low, high = ranges[key]
            row[key] = float(low + unit[i, j] * (high - low))
        row["power_share"] = float(share_low * (share_high / share_low) ** unit[i, -1])  # log-uniform
        row["gap_mm"] = float(rng.choice(s2["gaps_mm"]))
        row["bubble_gas"] = str(rng.choice(s2["bubble_gas"]))
        plan.append(row)
    return plan


def stage2_row(row: dict[str, Any], settings: dict[str, Any]) -> dict[str, Any]:
    """Run the Stage 2 twin chain (bubble plasma, water, survival) for one planned row; the row is noise-free by design."""
    from plasma_twin.services import stage2
    from plasma_twin.stage2.bubble_model import solve
    from plasma_twin.stage2.hom import survival
    from plasma_twin.stage2.liquid import solve_liquid
    config = {**stage2.default_config(), **{k: v for k, v in row.items() if k != "index"}}
    bubble = solve(stage2.bubble_inputs(config))
    water = solve_liquid(bubble, stage2.water_inputs(config))
    kill = survival(water.time_s, water.ozone_mg_l, water.ozone_ct_mg_s_l, config["organism"], config["initial_count_cfu_ml"],
                    config["water_volume_ml"], config["water_temperature_c"], config["power_w"])
    return {**row, "te_ev": bubble.te_ev, "ne_m3": bubble.ne_m3, "o2_split": bubble.dissociated_o2_fraction,
            "ozone_mg_l": float(water.ozone_mg_l[-1]), "h2o2_mmol_l": float(water.h2o2_mmol_l[-1]), "oh_mol_l": float(water.oh_mol_l[-1]),
            "log_reduction": kill.log_reduction, "log_reduction_capped": kill.capped,
            "temperature_rise_c": water.temperature_after_c - water.temperature_before_c}


# ------------------------------------------------------------------------------------ building and storing
@dataclass(frozen=True)
class DatasetCard:
    dataset_id: str
    stage: int
    twin_version: str
    rows: int
    rows_per_fault: dict[str, int]
    seed: int
    lock_date: str
    created_at: str
    settings_file: str


def _worker(args):
    stage, row, settings = args
    return (stage1_row if stage == 1 else stage2_row)(row, settings)


def build(stage: int, runs: int | None = None, workers: int = 1, progress: Callable[[int, int], None] | None = None,
          settings_path: Path = SETTINGS_PATH) -> tuple[pd.DataFrame, DatasetCard]:
    """Generate a dataset. `runs` is only for tests: the published dataset uses the locked count."""
    settings = load_settings(settings_path)
    plan = (stage1_plan if stage == 1 else stage2_plan)(settings, runs)
    jobs = [(stage, row, settings) for row in plan]
    rows: list[dict[str, Any]] = []
    if workers > 1:
        with ProcessPoolExecutor(max_workers=workers) as pool:
            for k, out in enumerate(pool.map(_worker, jobs, chunksize=4)):
                rows.append(out)
                if progress:
                    progress(k + 1, len(jobs))
    else:
        for k, job in enumerate(jobs):
            rows.append(_worker(job))
            if progress:
                progress(k + 1, len(jobs))
    frame = pd.DataFrame(rows).sort_values("index").reset_index(drop=True)
    faults = frame["fault"].value_counts().to_dict() if "fault" in frame else {}
    card = DatasetCard(dataset_id(stage, settings_path), stage, TWIN_VERSION, len(frame), {str(k): int(v) for k, v in faults.items()},
                       settings[f"stage{stage}"]["seed"], settings["lock"]["date"], datetime.now().isoformat(timespec="seconds"),
                       settings_path.name)
    return frame, card


def save(frame: pd.DataFrame, card: DatasetCard, folder: Path | None = None) -> Path:
    """Write a dataset and its card (settings, seed, twin version), so the exact training data can be traced (FR16.1)."""
    folder = folder or data_dir()
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / f"{card.dataset_id}.parquet"
    frame.to_parquet(path, index=False)
    (folder / f"{card.dataset_id}.json").write_text(json.dumps(card.__dict__, indent=2), encoding="utf-8")
    return path


def load(dataset: str, folder: Path | None = None) -> tuple[pd.DataFrame, DatasetCard]:
    """Read a saved dataset and its card by dataset ID."""
    folder = folder or data_dir()
    card = DatasetCard(**json.loads((folder / f"{dataset}.json").read_text(encoding="utf-8")))
    return pd.read_parquet(folder / f"{dataset}.parquet"), card


def cards(folder: Path | None = None) -> list[DatasetCard]:
    """The cards of every saved dataset, for the AI training screen (FR16.1)."""
    folder = folder or data_dir()
    return [DatasetCard(**json.loads(p.read_text(encoding="utf-8"))) for p in sorted(folder.glob("S*.json"))] if folder.exists() else []


# ------------------------------------------------------------------------------------ splits (FR16.3)
def in_region(frame: pd.DataFrame, stage: int, settings: dict[str, Any] | None = None) -> np.ndarray:
    """Rows inside the held-out corner of the envelope, used by the region split to test extrapolation (FR16.3)."""
    region = (settings or load_settings())["splits"][f"stage{stage}_region"]
    if stage == 1:
        return ((frame["rf_power_w"] >= region["rf_power_w_min"]) & (frame["pressure_mbar"] >= region["pressure_mbar_min"])).to_numpy()
    return ((frame["power_w"] >= region["power_w_min"]) & (frame["o2_flow_sccm"] >= region["o2_flow_sccm_min"])).to_numpy()


def split(frame: pd.DataFrame, stage: int, kind: str, settings: dict[str, Any] | None = None) -> tuple[np.ndarray, np.ndarray]:
    """(train, test) row positions. 'random': seeded 80/20. 'region': the held-out corner is the test set."""
    settings = settings or load_settings()
    if kind == "random":
        order = np.random.default_rng(settings["splits"]["seed"]).permutation(len(frame))
        cut = int(round(len(frame) * (1 - settings["splits"]["random_test_fraction"])))
        return np.sort(order[:cut]), np.sort(order[cut:])
    if kind == "region":
        held = in_region(frame, stage, settings)
        return np.flatnonzero(~held), np.flatnonzero(held)
    raise ValueError("split must be 'random' or 'region'")
